link from another user. You will be granted the invitation permission and taken directly into the session.</p><div class="join"><input id="invite" class="input" placeholder="Paste private session invite link here…"><button class="btn" onclick="joinInvite()">Join Session</button></div><div id="joinStatus" class="meta"></div></section><section class="panel"><h2>My Private Sessions</h2><div id="owned" class="grid"><div class="empty">Loading…</div></div></section><section class="panel"><h2>Shared With Me</h2><div id="shared" class="grid"><div class="empty">Loading…</div></div></section></div><script>const API=<?=json_encode(BASE_URL.'/API/collaboration/my-space.php')?>;function esc(s){return String(s??'').replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','\"':'&quot;'}[c]))}function card(r,shared){const icon=r.resource_type==='whiteboard'?'🖊':'📄';return '<article class="card"><div class="title">'+icon+' '+esc(r.title||'Untitled')+' <span class="tag private">Private</span></div><div class="meta">Owner: '+esc(r.owner_name||'Unknown')+(shared?' · Permission: '+esc(r.permission||'view'):' <span class="tag owner">Owner</span>')+'</div><button class="btn" onclick="location.href=\''+esc(r.open_url)+'\'">Open Session</button></article>'}async function load(){try{const r=await fetch(API,{credentials:'same-origin'});const d=await r.json();if(!r.ok||!d.success)throw Error(d.error||'Unable to load My Space.');document.getElementById('owned').innerHTML=d.owned.length?d.owned.map(x=>card(x,false)).join(''):'<div class="empty">You do not own any private sessions yet.</div>';document.getElementById('shared').innerHTML=d.shared.length?d.shared.map(x=>card(x,true)).join(''):'<div class="empty">No private sessions have been shared with you.</div>'}catch(e){document.getElementById('owned').innerHTML=document.getElementById('shared').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}function joinInvite(){const raw=document.getElementById('invite').value.trim();const s=document.getElementById('joinStatus');if(!raw)return s.textContent='Paste an invitation link first.';try{const u=new URL(raw,location.origin);if(!u.pathname.endsWith('/modules/collaboration/resource-invite.php'))throw Error('That is not a valid eCollab private-session invitation.');if(!u.searchParams.get('token'))throw Error('The invitation token is missing.');s.textContent='Opening invitation…';location.href=u.href}catch(e){s.textContent=e.message}}load();</script></body></html>